async function allIn(name: string, minLvl: number): Promise<string> {
  const re = new RegExp('^' + name + '$', 'i');
  while (Date.now() < DEADLINE - 4000) {
    const npcs = sdk.getState().nearbyNpcs.filter((n:any)=> re.test(n.name) && n.reachable !== false && (n.combatLevel??0) >= minLvl);
    if (!npcs.length) return 'NONE_FOUND';
    npcs.sort((a:any,b:any)=> (b.combatLevel??0)-(a.combatLevel??0));
    const npc = npcs[0]; const idx = npc.index; const lvl = npc.combatLevel ?? 0;
    const xp0 = sdk.getSkillXp('Hitpoints');
    await bot.attack(npc);
    const t0 = Date.now(); let lastAtk = Date.now();
    while (Date.now() - t0 < 50000 && Date.now() < DEADLINE - 3000) {
      await sdk.waitForTicks(1);
      const st = sdk.getState();
      if (st.player.isDead) return 'DIED';
      const still = st.nearbyNpcs.find((n:any)=> n.index === idx);
      if (!still) {
        if (sdk.getSkillXp('Hitpoints') > xp0) return 'KILLED lvl ' + lvl;
        break;
      }
      if (Date.now() - lastAtk > 3000) { await bot.attack(still); lastAtk = Date.now(); }
    }
    if (sdk.getState().player.isDead) return 'DIED';
  }
  return 'OUT_OF_TIME';
}
